-- Assign permissions to user role (basic settings)
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.name = 'user' AND p.name LIKE 'settings.%' AND p.name != 'settings.*'
ON CONFLICT DO NOTHING;

-- Assign wildcard permissions to admin role (covers all current and future permissions)
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.name = 'admin' AND (p.name IN ('admin.*', 'settings.*') OR p.name LIKE 'admin.developer.%')
ON CONFLICT DO NOTHING;

-- Grant admin role full access to all models by default
INSERT INTO model_access (role_id, can_use, can_configure)
SELECT id, true, true FROM roles WHERE name = 'admin'
ON CONFLICT DO NOTHING;

-- ============= Tool Calling Infrastructure =============

-- Tool source types
DO $$ BEGIN
    CREATE TYPE tool_source_kind AS ENUM (
        'BUILTIN',       -- Built-in tools (Exa search, etc.)
        'WASM',          -- Extism WASM plugins
        'MCP',           -- MCP server connection
        'HTTP'           -- HTTP endpoint tools
    );
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

-- WASM blobs storage for compiled plugins
CREATE TABLE IF NOT EXISTS wasm_blobs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID REFERENCES users(id) ON DELETE CASCADE,
    original_filename VARCHAR(255),
    compiled_from VARCHAR(50),  -- 'rust', 'javascript', 'wasm' (direct upload)
    blob BYTEA NOT NULL,
    size_bytes INTEGER NOT NULL,
    sha256_hash VARCHAR(64) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Tools table - defines available tools
CREATE TABLE IF NOT EXISTS tools (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID REFERENCES users(id) ON DELETE CASCADE,  -- NULL = system tool

    name VARCHAR(100) NOT NULL,
    display_name VARCHAR(255) NOT NULL,
    description TEXT,
    icon VARCHAR(500),

    source_kind tool_source_kind NOT NULL,
    source_config JSONB NOT NULL DEFAULT '{}',  -- Kind-specific config

    -- JSON Schema for tool parameters (passed to LLM)
    input_schema JSONB NOT NULL,

    -- Custom settings schema (API keys, user config) - NOT passed to LLM
    settings_schema JSONB DEFAULT '{}',
    system_prompt TEXT,

    -- Permissions
    is_enabled BOOLEAN DEFAULT true,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(owner_id, name)
);

-- User-provided settings for tools (API keys, etc.)
CREATE TABLE IF NOT EXISTS user_tool_settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    tool_id UUID NOT NULL REFERENCES tools(id) ON DELETE CASCADE,
    settings JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Partial unique index for system-wide settings (user_id IS NULL)
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_tool_settings_tool_null_user ON user_tool_settings(tool_id)
WHERE user_id IS NULL;

-- Partial unique index for per-user settings (user_id IS NOT NULL)
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_tool_settings_user_tool_not_null ON user_tool_settings(user_id, tool_id)
WHERE user_id IS NOT NULL;

-- MCP Servers - for MCP tool sources (Streamable HTTP transport)
CREATE TABLE IF NOT EXISTS mcp_servers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID REFERENCES users(id) ON DELETE CASCADE,

    name VARCHAR(100) NOT NULL,
    transport VARCHAR(50) NOT NULL,  -- 'http'
    connection_config JSONB NOT NULL,  -- {url, headers}

    is_enabled BOOLEAN DEFAULT true,
    last_health_check TIMESTAMPTZ,
    health_status VARCHAR(50),

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(owner_id, name)
);

-- Create tool_functions table
CREATE TABLE IF NOT EXISTS tool_functions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tool_id UUID NOT NULL REFERENCES tools(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    input_schema JSONB NOT NULL,
    entrypoint VARCHAR(255),               -- Optional override for WASM/HTTP routing
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(tool_id, name)
);

-- Tool executions - audit log for tool calls
CREATE TABLE IF NOT EXISTS tool_executions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    message_id UUID REFERENCES messages(id) ON DELETE SET NULL,
    tool_id UUID REFERENCES tools(id) ON DELETE SET NULL,
    tool_function UUID REFERENCES tool_functions(id) ON DELETE SET NULL,

    tool_call_id VARCHAR(255) NOT NULL,  -- From LLM
    input_args JSONB NOT NULL,
    output JSONB,
    error TEXT,

    execution_ms INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Gateway catalog

DO $$ BEGIN
    CREATE TYPE gateway_availability AS ENUM (
        'AVAILABLE',
        'USER_UNAVAILABLE'
    );
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

CREATE TABLE IF NOT EXISTS gateway_catalog_models (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    provider_id UUID NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    source_gateway VARCHAR(50) NOT NULL,            -- e.g. 'openrouter'
    gateway_model_id TEXT NOT NULL,                 -- bare 'author/slug'
    local_model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    display_name TEXT NOT NULL DEFAULT '',
    availability_state gateway_availability NOT NULL DEFAULT 'AVAILABLE',
    reason TEXT,
    raw JSONB NOT NULL DEFAULT '{}',
    fetched_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (provider_id, source_gateway, gateway_model_id)
);

CREATE TABLE IF NOT EXISTS gateway_model_provider_options (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    catalog_model_id UUID NOT NULL REFERENCES gateway_catalog_models(id) ON DELETE CASCADE,
    provider_slug TEXT,                             -- endpoint tag, e.g. 'openai'
    provider_name TEXT,
    endpoint_name TEXT,
    status DOUBLE PRECISION,                        -- OpenRouter health status (0 = healthy)
    quantization TEXT,
    context_length INTEGER,
    max_completion_tokens INTEGER,
    latency DOUBLE PRECISION,                       -- p50 latency (seconds)
    throughput DOUBLE PRECISION,                    -- p50 throughput (tokens/sec)
    uptime DOUBLE PRECISION,                        -- uptime over last 30m (percent)
    price_input DOUBLE PRECISION,                   -- USD per million input tokens
    price_output DOUBLE PRECISION,                  -- USD per million output tokens
    raw JSONB NOT NULL DEFAULT '{}',
    fetched_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_gateway_catalog_models_provider ON gateway_catalog_models(provider_id);

-- Upstream providers of routing provider kinds (e.g. OpenRouter), synced by provider_routing::sources
CREATE TABLE IF NOT EXISTS upstream_gateways (
    kind provider_kind PRIMARY KEY,
    synced_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS upstream_providers (
    kind provider_kind NOT NULL REFERENCES upstream_gateways(kind) ON DELETE CASCADE,
    slug TEXT NOT NULL,
    name TEXT,
    headquarters TEXT,
    datacenters TEXT[] NOT NULL DEFAULT '{}',
    PRIMARY KEY (kind, slug)
);
CREATE INDEX IF NOT EXISTS idx_gateway_catalog_models_local ON gateway_catalog_models(local_model_id);
CREATE INDEX IF NOT EXISTS idx_gateway_catalog_models_availability ON gateway_catalog_models(availability_state);
CREATE INDEX IF NOT EXISTS idx_gateway_provider_options_catalog ON gateway_model_provider_options(catalog_model_id);


-- Teams
CREATE TABLE IF NOT EXISTS teams (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(100) NOT NULL UNIQUE,
    description TEXT,
    is_default BOOLEAN NOT NULL DEFAULT false,
    allow_all_models BOOLEAN NOT NULL DEFAULT false,
    budget_id UUID,
    default_model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    gateway_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    gateway_max_concurrent_requests INTEGER CONSTRAINT teams_gateway_max_concurrent_requests_check CHECK (gateway_max_concurrent_requests > 0),
    provider_selector_enabled BOOLEAN,
    allowed_upstream_providers JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS teams_single_default ON teams (is_default) WHERE is_default = true;

CREATE TABLE IF NOT EXISTS team_members (
    team_id UUID NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role VARCHAR NOT NULL DEFAULT 'member' CONSTRAINT team_members_role_check CHECK (role IN ('member', 'admin')),
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (team_id, user_id)
);

CREATE TABLE IF NOT EXISTS team_model_access (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    team_id UUID NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
    provider_id UUID REFERENCES providers(id) ON DELETE CASCADE,
    model_id UUID REFERENCES models(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT team_model_access_target_check CHECK (
        (provider_id IS NOT NULL AND model_id IS NULL) OR
        (provider_id IS NULL AND model_id IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS team_model_access_provider_unique ON team_model_access (team_id, provider_id) WHERE provider_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS team_model_access_model_unique ON team_model_access (team_id, model_id) WHERE model_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS team_permissions (
    team_id UUID NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
    permission_id UUID NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
    is_allowed BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (team_id, permission_id)
);

CREATE INDEX IF NOT EXISTS idx_teams_default ON teams(is_default) WHERE is_default = true;
CREATE INDEX IF NOT EXISTS idx_team_members_team ON team_members(team_id);
CREATE INDEX IF NOT EXISTS idx_team_members_user ON team_members(user_id);
CREATE INDEX IF NOT EXISTS idx_team_members_team_role ON team_members(team_id) WHERE role = 'admin';
CREATE INDEX IF NOT EXISTS idx_team_model_access_team ON team_model_access(team_id);
CREATE INDEX IF NOT EXISTS idx_team_model_access_provider ON team_model_access(provider_id);
CREATE INDEX IF NOT EXISTS idx_team_model_access_model ON team_model_access(model_id);
CREATE INDEX IF NOT EXISTS idx_team_permissions_permission ON team_permissions(permission_id);

INSERT INTO teams (name, description, is_default, allow_all_models)
VALUES ('General', 'Default team for all users', true, true)
ON CONFLICT (name) DO NOTHING;

-- Gateway API keys and rate limits
CREATE TABLE IF NOT EXISTS gateway_api_keys (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    team_id UUID NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    secret_hash TEXT NOT NULL,
    key_prefix VARCHAR(48) NOT NULL,
    last_four VARCHAR(4) NOT NULL,
    scopes JSONB NOT NULL DEFAULT '["inference:read", "inference:write"]'::jsonb,
    is_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    max_concurrent_requests INTEGER CONSTRAINT gateway_api_keys_max_concurrent_requests_check CHECK (max_concurrent_requests > 0),
    expires_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    last_used_at TIMESTAMPTZ,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    revoked_by UUID REFERENCES users(id) ON DELETE SET NULL,
    admin_disabled_at TIMESTAMPTZ,
    admin_disabled_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS gateway_api_keys_prefix_idx ON gateway_api_keys(key_prefix);
CREATE INDEX IF NOT EXISTS gateway_api_keys_team_idx ON gateway_api_keys(team_id);
CREATE INDEX IF NOT EXISTS gateway_api_keys_user_idx ON gateway_api_keys(user_id);
CREATE INDEX IF NOT EXISTS gateway_api_keys_expires_idx ON gateway_api_keys(expires_at) WHERE revoked_at IS NULL AND expires_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS gateway_api_keys_last_used_idx ON gateway_api_keys(last_used_at);

CREATE TABLE IF NOT EXISTS gateway_rate_limit_rules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    team_id UUID REFERENCES teams(id) ON DELETE CASCADE,
    api_key_id UUID REFERENCES gateway_api_keys(id) ON DELETE CASCADE,
    route_class VARCHAR NOT NULL CONSTRAINT gateway_rate_limit_rules_route_class_check CHECK (route_class IN ('inference', 'utility')),
    metric VARCHAR NOT NULL CONSTRAINT gateway_rate_limit_rules_metric_check CHECK (metric IN ('requests', 'tokens')),
    capacity BIGINT NOT NULL CONSTRAINT gateway_rate_limit_rules_capacity_check CHECK (capacity > 0),
    refill_period_seconds INTEGER NOT NULL CONSTRAINT gateway_rate_limit_rules_refill_period_seconds_check CHECK (refill_period_seconds > 0),
    is_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT gateway_rate_limit_rules_scope_check CHECK ((team_id IS NULL) <> (api_key_id IS NULL)),
    CONSTRAINT gateway_utility_requests_only CHECK (route_class <> 'utility' OR metric = 'requests')
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_gateway_rate_limit_rules_team_window ON gateway_rate_limit_rules (team_id, route_class, metric, refill_period_seconds) WHERE team_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_gateway_rate_limit_rules_key_window ON gateway_rate_limit_rules (api_key_id, route_class, metric, refill_period_seconds) WHERE api_key_id IS NOT NULL;

-- Budgets and analytics
DO $$ BEGIN
    CREATE TYPE budget_kind AS ENUM ('pooled', 'per_user');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE budget_interval AS ENUM ('daily', 'weekly', 'monthly', 'total');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE budget_reset_strategy AS ENUM ('calendar', 'rolling', 'anchored');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE budget_on_exceed AS ENUM ('block', 'warn', 'allow');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

CREATE TABLE IF NOT EXISTS budgets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(120) NOT NULL,
    description TEXT,
    amount NUMERIC(12,4) NOT NULL CHECK (amount >= 0),
    kind budget_kind NOT NULL,
    interval budget_interval NOT NULL,
    reset_strategy budget_reset_strategy NOT NULL DEFAULT 'calendar',
    on_exceed budget_on_exceed NOT NULL DEFAULT 'block',
    is_enabled BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS budget_assignments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    budget_id UUID NOT NULL REFERENCES budgets(id) ON DELETE CASCADE,
    team_id UUID REFERENCES teams(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    api_key_id UUID REFERENCES gateway_api_keys(id) ON DELETE CASCADE,
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT budget_assignments_target_check CHECK (
        num_nonnulls(team_id, user_id, api_key_id) = 1
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS budget_assignments_team_budget_unique
    ON budget_assignments (team_id, budget_id)
    WHERE team_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS budget_assignments_user_budget_unique
    ON budget_assignments (user_id, budget_id)
    WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS budget_assignments_api_key_unique
    ON budget_assignments (api_key_id)
    WHERE api_key_id IS NOT NULL;

CREATE OR REPLACE FUNCTION delete_api_key_budget() RETURNS trigger AS $$
BEGIN
    DELETE FROM budgets WHERE id = OLD.budget_id AND NOT EXISTS (SELECT 1 FROM budget_assignments WHERE budget_id = OLD.budget_id);
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS budget_assignments_delete_api_key_budget ON budget_assignments;
CREATE TRIGGER budget_assignments_delete_api_key_budget
    AFTER DELETE ON budget_assignments
    FOR EACH ROW
    WHEN (OLD.api_key_id IS NOT NULL)
    EXECUTE FUNCTION delete_api_key_budget();

-- Presets: a base model with instructions, sampling, reasoning and tools, addressed as presets/<slug>
CREATE TABLE IF NOT EXISTS model_presets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    scope VARCHAR(20) NOT NULL CONSTRAINT model_presets_scope_check CHECK (scope IN ('personal', 'team', 'installation')),
    owner_id UUID REFERENCES users(id) ON DELETE CASCADE,
    team_id UUID REFERENCES teams(id) ON DELETE CASCADE,
    slug VARCHAR(64) NOT NULL CONSTRAINT model_presets_slug_check CHECK (slug ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(/[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$'),
    name VARCHAR(100) NOT NULL,
    description TEXT,
    icon VARCHAR(500),
    base_model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    system_prompt TEXT,
    sampling JSONB NOT NULL DEFAULT '{}',
    reasoning JSONB NOT NULL DEFAULT '{}',
    levels JSONB NOT NULL DEFAULT '[]' CONSTRAINT model_presets_levels_check CHECK (jsonb_typeof(levels) = 'array' AND jsonb_array_length(levels) <= 5),
    default_level VARCHAR(32),
    tool_ids UUID[] NOT NULL DEFAULT '{}',
    tools_locked BOOLEAN NOT NULL DEFAULT false,
    starters TEXT[] NOT NULL DEFAULT '{}' CONSTRAINT model_presets_starters_check CHECK (cardinality(starters) <= 4),
    prompt_visible BOOLEAN NOT NULL DEFAULT true,
    is_enabled BOOLEAN NOT NULL DEFAULT true,
    disabled_by_admin BOOLEAN NOT NULL DEFAULT false,
    shared_with_everyone BOOLEAN NOT NULL DEFAULT false,
    mode VARCHAR(10) NOT NULL DEFAULT 'standard' CONSTRAINT model_presets_mode_check CHECK (mode IN ('standard', 'arena')),
    arena JSONB NOT NULL DEFAULT '{}',
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    deleted_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT model_presets_scope_owner_check CHECK (
        (scope = 'personal' AND owner_id IS NOT NULL AND team_id IS NULL) OR
        (scope = 'team' AND team_id IS NOT NULL AND owner_id IS NULL) OR
        (scope = 'installation' AND owner_id IS NULL AND team_id IS NULL)
    ),
    CONSTRAINT model_presets_arena_scope_check CHECK (mode <> 'arena' OR scope <> 'personal')
);

CREATE UNIQUE INDEX IF NOT EXISTS model_presets_slug_unique ON model_presets (slug) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_model_presets_owner ON model_presets(owner_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_model_presets_team ON model_presets(team_id) WHERE deleted_at IS NULL;

-- Users and teams a preset is shared with on top of its own scope: viewers may use it, editors may also change it
CREATE TABLE IF NOT EXISTS model_preset_shares (
    preset_id UUID NOT NULL REFERENCES model_presets(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    team_id UUID REFERENCES teams(id) ON DELETE CASCADE,
    role VARCHAR(10) NOT NULL DEFAULT 'viewer' CONSTRAINT model_preset_shares_role_check CHECK (role IN ('viewer', 'editor')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT model_preset_shares_target_check CHECK ((user_id IS NULL) <> (team_id IS NULL))
);

CREATE UNIQUE INDEX IF NOT EXISTS model_preset_shares_user_unique ON model_preset_shares (preset_id, user_id) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS model_preset_shares_team_unique ON model_preset_shares (preset_id, team_id) WHERE team_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_model_preset_shares_user ON model_preset_shares(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_model_preset_shares_team ON model_preset_shares(team_id) WHERE team_id IS NOT NULL;

-- Arena rounds: one blind comparison of an arena preset's models; candidates are inactive assistant messages until one is picked
CREATE TABLE IF NOT EXISTS arena_rounds (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    preset_id UUID NOT NULL REFERENCES model_presets(id),
    chat_id UUID NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    user_message_id UUID NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    winner_message_id UUID REFERENCES messages(id) ON DELETE SET NULL,
    winner_model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    decided_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_arena_rounds_preset ON arena_rounds(preset_id);
CREATE INDEX IF NOT EXISTS idx_arena_rounds_chat ON arena_rounds(chat_id);

ALTER TABLE messages ADD COLUMN IF NOT EXISTS arena_round_id UUID REFERENCES arena_rounds(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_messages_arena_round ON messages(arena_round_id) WHERE arena_round_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS usage_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    team_id UUID REFERENCES teams(id) ON DELETE SET NULL,
    api_key_id UUID REFERENCES gateway_api_keys(id) ON DELETE SET NULL,
    model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    preset_id UUID REFERENCES model_presets(id) ON DELETE SET NULL,
    provider_id UUID REFERENCES providers(id) ON DELETE SET NULL,
    request_type VARCHAR(50) NOT NULL,
    input_tokens INTEGER NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
    output_tokens INTEGER NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
    reasoning_tokens INTEGER NOT NULL DEFAULT 0 CHECK (reasoning_tokens >= 0),
    cost_total NUMERIC(12,6) NOT NULL DEFAULT 0 CHECK (cost_total >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_usage_events_user_created ON usage_events(user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_usage_events_model_created ON usage_events(model_id, created_at);
CREATE INDEX IF NOT EXISTS idx_usage_events_team_created ON usage_events(team_id, created_at);
CREATE INDEX IF NOT EXISTS idx_usage_events_api_key_created ON usage_events(api_key_id, created_at);

CREATE TABLE IF NOT EXISTS gateway_request_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    request_id UUID,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    team_id UUID REFERENCES teams(id) ON DELETE SET NULL,
    api_key_id UUID REFERENCES gateway_api_keys(id) ON DELETE SET NULL,
    model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    preset_id UUID REFERENCES model_presets(id) ON DELETE SET NULL,
    public_model_id VARCHAR NOT NULL,
    provider VARCHAR,
    request_type VARCHAR(50) NOT NULL,
    status VARCHAR(20) NOT NULL CONSTRAINT gateway_request_logs_status_check CHECK (status IN ('success', 'error')),
    status_code INTEGER,
    error_category VARCHAR(50),
    finish_reason TEXT CONSTRAINT gateway_request_logs_finish_reason_check CHECK (finish_reason IN ('stop', 'length', 'tool_calls', 'content_filter')),
    streaming BOOLEAN NOT NULL DEFAULT FALSE,
    latency_ms INTEGER CONSTRAINT gateway_request_logs_latency_check CHECK (latency_ms >= 0),
    time_to_first_token_ms INTEGER,
    input_tokens INTEGER NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
    output_tokens INTEGER NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
    reasoning_tokens INTEGER NOT NULL DEFAULT 0 CHECK (reasoning_tokens >= 0),
    cost_total NUMERIC(12,6) NOT NULL DEFAULT 0 CHECK (cost_total >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_gateway_request_logs_user_created ON gateway_request_logs(user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_gateway_request_logs_key_created ON gateway_request_logs(api_key_id, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_gateway_request_logs_request_id ON gateway_request_logs(request_id) WHERE request_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_gateway_request_logs_preset ON gateway_request_logs(preset_id) WHERE preset_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS request_log_retention (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    retention_days INTEGER NOT NULL DEFAULT 30
        CONSTRAINT request_log_retention_days_check CHECK (retention_days BETWEEN 1 AND 3650),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS model_pricing_overrides (
    model_id UUID PRIMARY KEY REFERENCES models(id) ON DELETE CASCADE,
    pricing JSONB NOT NULL CHECK (
        jsonb_typeof(pricing) = 'object'
        AND (NOT pricing ? 'input' OR (jsonb_typeof(pricing->'input') = 'number' AND (pricing->>'input')::numeric >= 0))
        AND (NOT pricing ? 'output' OR (jsonb_typeof(pricing->'output') = 'number' AND (pricing->>'output')::numeric >= 0))
        AND (NOT pricing ? 'tiers' OR jsonb_typeof(pricing->'tiers') = 'array')
        AND (NOT pricing ? 'service_tiers' OR jsonb_typeof(pricing->'service_tiers') = 'object')
        AND (NOT pricing ? 'windows' OR jsonb_typeof(pricing->'windows') = 'array')
    ),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS budget_reset_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    assignment_id UUID REFERENCES budget_assignments(id) ON DELETE CASCADE,
    budget_id UUID REFERENCES budgets(id) ON DELETE CASCADE,
    team_id UUID REFERENCES teams(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    kind budget_kind,
    reason TEXT,
    reset_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT budget_reset_events_scope_check CHECK (
        num_nonnulls(assignment_id, budget_id, team_id, user_id) = 1
    )
);

CREATE INDEX IF NOT EXISTS idx_budget_reset_events_assignment ON budget_reset_events(assignment_id, reset_at);
CREATE INDEX IF NOT EXISTS idx_budget_reset_events_budget ON budget_reset_events(budget_id, reset_at);
CREATE INDEX IF NOT EXISTS idx_budget_reset_events_team ON budget_reset_events(team_id, reset_at);
CREATE INDEX IF NOT EXISTS idx_budget_reset_events_user ON budget_reset_events(user_id, reset_at);
-- Provider billing
CREATE TABLE IF NOT EXISTS provider_billing_connections (
    provider_id UUID PRIMARY KEY REFERENCES providers(id) ON DELETE CASCADE,
    credential TEXT,
    external_scope_id TEXT,
    external_scope_name TEXT,
    is_enabled BOOLEAN NOT NULL DEFAULT false,
    last_status TEXT NOT NULL DEFAULT 'NOT_CONFIGURED',
    last_error_code TEXT,
    last_synced_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT provider_billing_status_check CHECK (
        last_status IN ('NOT_CONFIGURED', 'AVAILABLE', 'UNSUPPORTED', 'UNAUTHORIZED', 'UPSTREAM_ERROR')
    )
);

CREATE TABLE IF NOT EXISTS provider_billing_snapshots (
    provider_id UUID PRIMARY KEY REFERENCES providers(id) ON DELETE CASCADE,
    metric_kind TEXT NOT NULL,
    currency TEXT NOT NULL,
    period_start TIMESTAMPTZ,
    period_end TIMESTAMPTZ,
    limit_amount NUMERIC,
    spent_amount NUMERIC,
    remaining_amount NUMERIC,
    is_hard_limit BOOLEAN NOT NULL DEFAULT false,
    thresholds JSONB NOT NULL DEFAULT '[]'::jsonb,
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    fetched_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT provider_billing_metric_kind_check CHECK (
        metric_kind IN ('CREDIT_BALANCE', 'KEY_LIMIT', 'SPEND_THRESHOLD', 'SPEND_ONLY')
    )
);

-- Knowledge (RAG): connections to vector stores and the models that index and rerank knowledge
CREATE TABLE IF NOT EXISTS rag_connections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL UNIQUE CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
    kind TEXT NOT NULL CHECK (kind IN ('pgvector', 'qdrant')),
    mode TEXT NOT NULL CHECK (mode IN ('managed', 'read_only')),
    -- NULL: the main database (managed pgvector only). Never holds a password.
    url TEXT,
    -- Encrypted Postgres password or Qdrant API key.
    secret TEXT,
    embedding_model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    -- Requested from the model; NULL sends no dimensions and takes the model default.
    dimensions INTEGER CHECK (dimensions BETWEEN 1 AND 4000),
    -- What the test embedding returned: the size of every vector in this connection.
    vector_size INTEGER CHECK (vector_size BETWEEN 1 AND 4000),
    index_generation INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (mode = 'read_only' OR kind = 'pgvector'),
    CHECK (url IS NOT NULL OR (kind = 'pgvector' AND mode = 'managed')),
    CHECK (mode = 'managed' OR (embedding_model_id IS NULL AND dimensions IS NULL AND vector_size IS NULL)),
    CHECK (embedding_model_id IS NULL OR vector_size IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS rag_config (
    id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (id),
    reranker_model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    reranker_top_n INTEGER NOT NULL DEFAULT 6 CHECK (reranker_top_n BETWEEN 1 AND 50),
    default_connection_id UUID REFERENCES rag_connections(id) ON DELETE SET NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO rag_config DEFAULT VALUES ON CONFLICT DO NOTHING;

-- Knowledge bases: views onto collections of read-only connections, shared with users, teams, roles or everyone.

CREATE TABLE IF NOT EXISTS knowledge_bases (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
    description TEXT CHECK (description IS NULL OR char_length(description) <= 2000),
    -- A connection cannot be deleted while knowledge bases point at it.
    connection_id UUID NOT NULL REFERENCES rag_connections(id) ON DELETE RESTRICT,
    -- Collection, vector, embedding model, field mapping and fixed filter (`ExternalView`).
    view JSONB NOT NULL,
    shared_with_everyone BOOLEAN NOT NULL DEFAULT FALSE,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_knowledge_bases_connection ON knowledge_bases(connection_id);

CREATE TABLE IF NOT EXISTS knowledge_base_shares (
    knowledge_base_id UUID NOT NULL REFERENCES knowledge_bases(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    team_id UUID REFERENCES teams(id) ON DELETE CASCADE,
    role_id UUID REFERENCES roles(id) ON DELETE CASCADE,
    role TEXT NOT NULL DEFAULT 'viewer' CHECK (role IN ('viewer', 'editor')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (num_nonnulls(user_id, team_id, role_id) = 1),
    UNIQUE NULLS NOT DISTINCT (knowledge_base_id, user_id, team_id, role_id)
);

CREATE INDEX IF NOT EXISTS idx_knowledge_base_shares_user ON knowledge_base_shares(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_knowledge_base_shares_team ON knowledge_base_shares(team_id) WHERE team_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_knowledge_base_shares_role ON knowledge_base_shares(role_id) WHERE role_id IS NOT NULL;

-- Knowledge bases attached to chats and presets; the knowledge tool searches them for users who may.

CREATE TABLE IF NOT EXISTS chat_knowledge_bases (
    chat_id UUID NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
    knowledge_base_id UUID NOT NULL REFERENCES knowledge_bases(id) ON DELETE CASCADE,
    PRIMARY KEY (chat_id, knowledge_base_id)
);

CREATE TABLE IF NOT EXISTS preset_knowledge_bases (
    preset_id UUID NOT NULL REFERENCES model_presets(id) ON DELETE CASCADE,
    knowledge_base_id UUID NOT NULL REFERENCES knowledge_bases(id) ON DELETE CASCADE,
    PRIMARY KEY (preset_id, knowledge_base_id)
);

CREATE INDEX IF NOT EXISTS idx_chat_knowledge_bases_base ON chat_knowledge_bases(knowledge_base_id);
CREATE INDEX IF NOT EXISTS idx_preset_knowledge_bases_base ON preset_knowledge_bases(knowledge_base_id);

-- Which providers, upstream providers and models may see a knowledge base's content, and which chats hold it.
-- An empty list means no restriction. No foreign key on the knowledge base: the targets outlive a deleted base, so chats holding its excerpts stay restricted.
-- A deleted provider or model leaves its row with every column NULL, which allows nothing until the list is saved again.
CREATE TABLE IF NOT EXISTS knowledge_base_model_targets (
    knowledge_base_id UUID NOT NULL,
    provider_id UUID REFERENCES providers(id) ON DELETE SET NULL,
    model_id UUID REFERENCES models(id) ON DELETE SET NULL,
    -- Slug of an upstream provider of a routing provider (OpenRouter, Cortecs).
    upstream_provider TEXT CHECK (upstream_provider IS NULL OR upstream_provider ~ '^[a-z0-9._/-]{1,64}$'),
    CHECK (num_nonnulls(provider_id, model_id, upstream_provider) <= 1)
);

-- Knowledge bases whose excerpts are in a chat's history; only grows, so every later request of the chat keeps their restrictions.
CREATE TABLE IF NOT EXISTS chat_knowledge_sources (
    chat_id UUID NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
    knowledge_base_id UUID NOT NULL,
    PRIMARY KEY (chat_id, knowledge_base_id)
);

CREATE INDEX IF NOT EXISTS idx_chat_knowledge_sources_base ON chat_knowledge_sources(knowledge_base_id);
CREATE INDEX IF NOT EXISTS idx_knowledge_base_model_targets_base ON knowledge_base_model_targets(knowledge_base_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_knowledge_base_model_targets_provider ON knowledge_base_model_targets(knowledge_base_id, provider_id) WHERE provider_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_knowledge_base_model_targets_model ON knowledge_base_model_targets(knowledge_base_id, model_id) WHERE model_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_knowledge_base_model_targets_upstream ON knowledge_base_model_targets(knowledge_base_id, upstream_provider) WHERE upstream_provider IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_knowledge_base_model_targets_provider_id ON knowledge_base_model_targets(provider_id) WHERE provider_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_knowledge_base_model_targets_model_id ON knowledge_base_model_targets(model_id) WHERE model_id IS NOT NULL;

-- Per-record access: records of a knowledge base list labels, and these rows say which teams, roles and users hold each label.
-- A label without rows grants nobody.
CREATE TABLE IF NOT EXISTS knowledge_base_access_labels (
    knowledge_base_id UUID NOT NULL REFERENCES knowledge_bases(id) ON DELETE CASCADE,
    label TEXT NOT NULL CHECK (char_length(label) BETWEEN 1 AND 200),
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    team_id UUID REFERENCES teams(id) ON DELETE CASCADE,
    role_id UUID REFERENCES roles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (num_nonnulls(user_id, team_id, role_id) = 1),
    UNIQUE NULLS NOT DISTINCT (knowledge_base_id, label, user_id, team_id, role_id)
);

CREATE INDEX IF NOT EXISTS idx_knowledge_base_access_labels_user ON knowledge_base_access_labels(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_knowledge_base_access_labels_team ON knowledge_base_access_labels(team_id) WHERE team_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_knowledge_base_access_labels_role ON knowledge_base_access_labels(role_id) WHERE role_id IS NOT NULL;

