-- Model pricing translations
INSERT INTO i18n_translations (language, key_path, value) VALUES
    ('en', 'pricing.editor_desc', 'Override what this model is billed at. Anything you leave empty keeps the catalog price.'),
    ('de', 'pricing.editor_desc', 'Lege fest, wie dieses Modell abgerechnet wird. Leere Felder behalten den Katalogpreis.'),
    ('en', 'pricing.remove_override', 'Use catalog price'),
    ('de', 'pricing.remove_override', 'Katalogpreis verwenden'),
    ('en', 'pricing.catalog_price', 'Catalog price'),
    ('de', 'pricing.catalog_price', 'Katalogpreis'),
    ('en', 'pricing.billed_price', 'Billed price'),
    ('de', 'pricing.billed_price', 'Abgerechneter Preis'),
    ('en', 'pricing.no_price', 'No price known'),
    ('de', 'pricing.no_price', 'Kein Preis bekannt'),
    ('en', 'pricing.base_rates', 'Base rates'),
    ('de', 'pricing.base_rates', 'Grundpreise'),
    ('en', 'pricing.base_rates_hint', 'Token rates are in USD per million tokens, "per" rates in USD per unit. Empty fields use the catalog rate shown as placeholder.'),
